policy:
{
  // A partner tailnet shares some of its nodes with yours. externalTailnets
  // configures the relationship under a local alias ("partner"); the shared
  // nodes themselves come from the snapshot (see External tailnets there).
  //
  // Sharing is two policies, one per tailnet. This is YOUR half:
  //   - allowIncomingConnections: true  -> you are the SHARING side. Your
  //     grants may use group://partner/<name> / tag://partner/<name> as a
  //     src, pointing at your own resources.
  //   - allowExternalReferencesTo        -> you are the RECEIVING side. The
  //     partner's policy may name these local tags/groups as a src.
  // No checklist — watch the "Declarative node sharing" panel.
  "tagOwners": {
    "tag:srv": ["alice@example.com"],
    "tag:client": ["alice@example.com"],
  },
  "externalTailnets": {
    "partner": {
      "externalID": "acme-42",
      "allowIncomingConnections": true,
      "allowExternalReferencesTo": ["tag:client"],
    },
  },
  "grants": [
    { "src": ["group://partner/eng"], "dst": ["tag:srv"], "ip": ["tcp:443"] },
    { "src": ["tag://partner/relay"], "dst": ["tag:srv"], "ip": ["tcp:22"] },
  ],
}
